import unittest

from progress import percent_complete


class Regression(unittest.TestCase):
    def test_it_rounds_to_the_nearest_percent(self):
        self.assertEqual(percent_complete(2, 3), 67)
        self.assertEqual(percent_complete(1, 64), 2)

    def test_the_ends(self):
        self.assertEqual(percent_complete(0, 64), 0)
        self.assertEqual(percent_complete(64, 64), 100)

    def test_an_empty_plan_is_zero_percent(self):
        self.assertEqual(percent_complete(0, 0), 0)

