def percent_complete(done, total):
    """Whole-number percentage of days done, rounded to the nearest percent. 0 when total is 0."""
    if total == 0:
        return 0
    # // floors before the multiplication, so any partial progress became 0. Divide with /, then round.
    return round(done * 100 / total)
